package com.ecole.gestion_scolaire.teacherportal.service;
import com.ecole.gestion_scolaire.common.exception.*; import com.ecole.gestion_scolaire.hr.entity.*; import com.ecole.gestion_scolaire.hr.repository.*; import com.ecole.gestion_scolaire.identity.repository.UserAccountRepository; import com.ecole.gestion_scolaire.registration.enums.EnrollmentStatus; import com.ecole.gestion_scolaire.registration.repository.StudentEnrollmentRepository; import com.ecole.gestion_scolaire.student.repository.StudentRepository; import com.ecole.gestion_scolaire.attendance.entity.TeacherAttendance; import com.ecole.gestion_scolaire.attendance.repository.TeacherAttendanceRepository; import com.ecole.gestion_scolaire.payroll.entity.Payroll; import com.ecole.gestion_scolaire.payroll.repository.*; import com.ecole.gestion_scolaire.timetable.dto.ScheduleEntryResponse; import com.ecole.gestion_scolaire.timetable.service.TimetableService; import com.ecole.gestion_scolaire.teacherportal.dto.TeacherPortalDtos.*; import com.ecole.gestion_scolaire.teacherportal.entity.*; import com.ecole.gestion_scolaire.teacherportal.repository.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @Transactional public class TeacherPortalService {
 private final UserAccountRepository users; private final TeacherRepository teachers; private final TeachingAssignmentRepository assignments; private final StudentEnrollmentRepository enrollments; private final StudentRepository students; private final TeacherAttendanceRepository attendances; private final PayrollRepository payrolls; private final SalaryPaymentRepository payments; private final TimetableService timetable; private final TeacherExerciseRepository exercises; private final TeacherEvaluationRepository evaluations; private final TeacherEvaluationGradeRepository grades;
 public TeacherPortalService(UserAccountRepository u,TeacherRepository t,TeachingAssignmentRepository a,StudentEnrollmentRepository e,StudentRepository s,TeacherAttendanceRepository at,PayrollRepository p,SalaryPaymentRepository sp,TimetableService tt,TeacherExerciseRepository x,TeacherEvaluationRepository ev,TeacherEvaluationGradeRepository g){users=u;teachers=t;assignments=a;enrollments=e;students=s;attendances=at;payrolls=p;payments=sp;timetable=tt;exercises=x;evaluations=ev;grades=g;}
 private Teacher current(){var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null)throw new BusinessRuleException("Utilisateur non authentifié");var u=users.findByUsername(auth.getName()).orElseThrow(()->new BusinessRuleException("Compte utilisateur introuvable"));return teachers.findByEmployeePersonId(u.getPerson().getId()).orElseThrow(()->new BusinessRuleException("Ce compte n'est pas lié à un enseignant"));}
 @Transactional(readOnly=true) public Me me(){var t=current();var e=t.getEmployee();var p=e.getPerson();return new Me(t.getId(),e.getId(),e.getEmployeeNumber(),p.getFirstName(),p.getLastName(),p.getEmail());}
 @Transactional(readOnly=true) public List<Assignment> myAssignments(){var t=current();return assignments.findByTeacherIdOrderByStartDateDesc(t.getId()).stream().map(a->new Assignment(a.getId(),a.getSchoolYear().getId(),a.getClassGroup().getId(),a.getClassGroup().getName(),a.getSubject().getId(),a.getSubject().getName(),a.getStartDate(),a.getEndDate(),a.getStatus().name())).toList();}
 @Transactional(readOnly=true) public List<StudentItem> students(Long assignmentId){var a=ownedAssignment(assignmentId);return enrollments.findActiveClass(a.getSchoolYear().getId(),a.getClassGroup().getId(),EnrollmentStatus.ACTIVE).stream().map(e->{var s=e.getStudent();var p=s.getPerson();return new StudentItem(s.getId(),s.getStudentNumber(),p.getFirstName(),p.getLastName(),s.getStatus());}).toList();}
 @Transactional(readOnly=true) public List<ScheduleEntryResponse> timetable(Long schoolYearId){return timetable.byTeacher(schoolYearId,current().getId());}
 @Transactional(readOnly=true) public List<Attendance> attendance(LocalDate from,LocalDate to){var tid=current().getId();Specification<TeacherAttendance> spec=(root,q,cb)->{var ps=new ArrayList<jakarta.persistence.criteria.Predicate>();ps.add(cb.equal(root.get("teacher").get("id"),tid));var session=root.join("classSession");if(from!=null)ps.add(cb.greaterThanOrEqualTo(session.get("sessionDate"),from));if(to!=null)ps.add(cb.lessThanOrEqualTo(session.get("sessionDate"),to));return cb.and(ps.toArray(new jakarta.persistence.criteria.Predicate[0]));};return attendances.findAll(spec).stream().sorted(Comparator.comparing((TeacherAttendance a)->a.getClassSession().getSessionDate()).reversed()).map(a->new Attendance(a.getId(),a.getClassSession().getSessionDate(),a.getClassSession().getClassGroup().getName(),a.getClassSession().getSubject().getName(),a.getClassSession().getTimeSlot().getCode(),a.getAttendanceStatus().name(),a.getLateMinutes(),a.getReason(),a.getValidationStatus().name())).toList();}
 @Transactional(readOnly=true) public List<PayrollItem> payroll(){var e=current().getEmployee();var seen=new HashSet<Long>();var out=new ArrayList<PayrollItem>();for(var p:payrolls.findByEmployeeIdOrderByPayrollPeriodYearDescPayrollPeriodMonthDescVersionNumberDesc(e.getId())){if(!seen.add(p.getPayrollPeriod().getId()))continue;var paid=payments.findByPayrollIdOrderByPaymentDateDesc(p.getId()).stream().map(x->x.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);out.add(new PayrollItem(p.getId(),p.getPayrollPeriod().getYear(),p.getPayrollPeriod().getMonth(),p.getCompensationType().name(),p.getGrossSalary(),p.getNetSalary(),paid,p.getNetSalary().subtract(paid).max(BigDecimal.ZERO),p.getStatus()));}return out;}
 @Transactional(readOnly=true) public Dashboard dashboard(){var t=current();var as=myAssignments();var classCount=as.stream().map(Assignment::classGroupId).distinct().count();var studentCount=as.stream().flatMap(a->students(a.assignmentId()).stream()).map(StudentItem::studentId).distinct().count();var att=attendance(LocalDate.now().minusMonths(12),LocalDate.now());var pays=payroll();var last=pays.isEmpty()?null:pays.get(0);return new Dashboard(me(),classCount,studentCount,att.stream().filter(x->"PRESENT".equals(x.status())).count(),att.stream().filter(x->"ABSENT".equals(x.status())).count(),att.stream().filter(x->"RETARD".equals(x.status())).count(),last==null?BigDecimal.ZERO:last.netSalary(),last==null?BigDecimal.ZERO:last.remainingAmount());}
 public Exercise saveExercise(Long id,ExerciseRequest r){var t=current();var a=ownedAssignment(r.teachingAssignmentId());TeacherExercise x=id==null?new TeacherExercise():exercises.findById(id).filter(z->z.getTeacher().getId().equals(t.getId())).orElseThrow(()->new ResourceNotFoundException("Exercice introuvable"));x.setTeacher(t);x.setAssignment(a);x.setTitle(required(r.title(),"Titre obligatoire"));x.setDescription(r.description());x.setInstructions(r.instructions());x.setDueDate(r.dueDate());x.setAttachmentReference(r.attachmentReference());x.setStatus(norm(r.status(),"DRAFT"));return exercise(exercises.save(x));}
 @Transactional(readOnly=true) public List<Exercise> exercises(){return exercises.findByTeacherIdOrderByDueDateDescIdDesc(current().getId()).stream().map(this::exercise).toList();}
 public void deleteExercise(Long id){var t=current();var x=exercises.findById(id).filter(z->z.getTeacher().getId().equals(t.getId())).orElseThrow(()->new ResourceNotFoundException("Exercice introuvable"));exercises.delete(x);}
 public Evaluation saveEvaluation(Long id,EvaluationRequest r){var t=current();var a=ownedAssignment(r.teachingAssignmentId());if(r.evaluationDate()==null||r.maxScore()==null||r.maxScore().signum()<=0)throw new BusinessRuleException("Date et note maximale valides obligatoires");TeacherEvaluation x=id==null?new TeacherEvaluation():evaluations.findById(id).filter(z->z.getTeacher().getId().equals(t.getId())).orElseThrow(()->new ResourceNotFoundException("Évaluation introuvable"));x.setTeacher(t);x.setAssignment(a);x.setTitle(required(r.title(),"Titre obligatoire"));x.setEvaluationDate(r.evaluationDate());x.setMaxScore(r.maxScore());x.setCoefficient(r.coefficient()==null?BigDecimal.ONE:r.coefficient());x.setDescription(r.description());x.setStatus(norm(r.status(),"DRAFT"));return evaluation(evaluations.save(x));}
 @Transactional(readOnly=true) public List<Evaluation> evaluations(){return evaluations.findByTeacherIdOrderByEvaluationDateDescIdDesc(current().getId()).stream().map(this::evaluation).toList();}
 public List<Grade> saveGrades(Long evaluationId,List<GradeRequest> req){var ev=ownedEvaluation(evaluationId);var allowed=students(ev.getAssignment().getId()).stream().map(StudentItem::studentId).collect(java.util.stream.Collectors.toSet());for(var r:req){if(!allowed.contains(r.studentId()))throw new BusinessRuleException("Cet élève n'appartient pas à la classe de l'évaluation");if(!r.absent()&&(r.score()==null||r.score().signum()<0||r.score().compareTo(ev.getMaxScore())>0))throw new BusinessRuleException("Note invalide pour l'élève "+r.studentId());var g=grades.findByEvaluationIdAndStudentId(ev.getId(),r.studentId()).orElseGet(TeacherEvaluationGrade::new);g.setEvaluation(ev);g.setStudent(students.findById(r.studentId()).orElseThrow(()->new ResourceNotFoundException("Élève introuvable")));g.setAbsent(r.absent());g.setScore(r.absent()?null:r.score());g.setComment(r.comment());grades.save(g);}return grades(evaluationId);}
 @Transactional(readOnly=true) public List<Grade> grades(Long evaluationId){var ev=ownedEvaluation(evaluationId);var by=grades.findByEvaluationId(ev.getId()).stream().collect(java.util.stream.Collectors.toMap(g->g.getStudent().getId(),g->g));return students(ev.getAssignment().getId()).stream().map(s->{var g=by.get(s.studentId());return new Grade(g==null?null:g.getId(),s.studentId(),s.studentNumber(),s.firstName(),s.lastName(),g==null?null:g.getScore(),g!=null&&g.isAbsent(),g==null?null:g.getComment());}).toList();}
 private TeachingAssignment ownedAssignment(Long id){var t=current();return assignments.findById(id).filter(a->a.getTeacher().getId().equals(t.getId())).orElseThrow(()->new ResourceNotFoundException("Affectation pédagogique introuvable ou non autorisée"));}
 private TeacherEvaluation ownedEvaluation(Long id){var t=current();return evaluations.findById(id).filter(e->e.getTeacher().getId().equals(t.getId())).orElseThrow(()->new ResourceNotFoundException("Évaluation introuvable"));}
 private Exercise exercise(TeacherExercise x){var a=x.getAssignment();return new Exercise(x.getId(),a.getId(),a.getClassGroup().getId(),a.getClassGroup().getName(),a.getSubject().getId(),a.getSubject().getName(),x.getTitle(),x.getDescription(),x.getInstructions(),x.getDueDate(),x.getAttachmentReference(),x.getStatus());}
 private Evaluation evaluation(TeacherEvaluation x){var a=x.getAssignment();return new Evaluation(x.getId(),a.getId(),a.getClassGroup().getId(),a.getClassGroup().getName(),a.getSubject().getId(),a.getSubject().getName(),x.getTitle(),x.getEvaluationDate(),x.getMaxScore(),x.getCoefficient(),x.getDescription(),x.getStatus());}
 private String required(String s,String m){if(s==null||s.isBlank())throw new BusinessRuleException(m);return s.trim();} private String norm(String s,String d){return s==null||s.isBlank()?d:s.trim().toUpperCase(Locale.ROOT);}
}
